        "views": [
            {
                "name": "pg_stat_statements",
                "schema": "extensions",
                "definition": " SELECT userid,\n    dbid,\n    toplevel,\n    queryid,\n    query,\n    plans,\n    total_plan_time,\n    min_plan_time,\n    max_plan_time,\n    mean_plan_time,\n    stddev_plan_time,\n    calls,\n    total_exec_time,\n    min_exec_time,\n    max_exec_time,\n    mean_exec_time,\n    stddev_exec_time,\n    rows,\n    shared_blks_hit,\n    shared_blks_read,\n    shared_blks_dirtied,\n    shared_blks_written,\n    local_blks_hit,\n    local_blks_read,\n    local_blks_dirtied,\n    local_blks_written,\n    temp_blks_read,\n    temp_blks_written,\n    shared_blk_read_time,\n    shared_blk_write_time,\n    local_blk_read_time,\n    local_blk_write_time,\n    temp_blk_read_time,\n    temp_blk_write_time,\n    wal_records,\n    wal_fpi,\n    wal_bytes,\n    jit_functions,\n    jit_generation_time,\n    jit_inlining_count,\n    jit_inlining_time,\n    jit_optimization_count,\n    jit_optimization_time,\n    jit_emission_count,\n    jit_emission_time,\n    jit_deform_count,\n    jit_deform_time,\n    stats_since,\n    minmax_stats_since\n   FROM pg_stat_statements(true) pg_stat_statements(userid, dbid, toplevel, queryid, query, plans, total_plan_time, min_plan_time, max_plan_time, mean_plan_time, stddev_plan_time, calls, total_exec_time, min_exec_time, max_exec_time, mean_exec_time, stddev_exec_time, rows, shared_blks_hit, shared_blks_read, shared_blks_dirtied, shared_blks_written, local_blks_hit, local_blks_read, local_blks_dirtied, local_blks_written, temp_blks_read, temp_blks_written, shared_blk_read_time, shared_blk_write_time, local_blk_read_time, local_blk_write_time, temp_blk_read_time, temp_blk_write_time, wal_records, wal_fpi, wal_bytes, jit_functions, jit_generation_time, jit_inlining_count, jit_inlining_time, jit_optimization_count, jit_optimization_time, jit_emission_count, jit_emission_time, jit_deform_count, jit_deform_time, stats_since, minmax_stats_since);"
            },
            {
                "name": "pg_stat_statements_info",
                "schema": "extensions",
                "definition": " SELECT dealloc,\n    stats_reset\n   FROM pg_stat_statements_info() pg_stat_statements_info(dealloc, stats_reset);"
            },
            {
                "name": "admin_all_protections",
                "schema": "public",
                "definition": " SELECT p.id,\n    p.customer_number_id,\n    u.full_name AS customer_name,\n    u.phone AS customer_phone,\n    pn.number,\n    tp.name_ar AS provider_name,\n    pkg.name AS package_name,\n    p.starts_at,\n    p.expires_at,\n    p.status,\n    p.created_at\n   FROM (((((protections p\n     JOIN customer_numbers cn ON ((cn.id = p.customer_number_id)))\n     JOIN users u ON ((u.id = cn.customer_id)))\n     JOIN phone_numbers pn ON ((pn.id = cn.phone_number_id)))\n     JOIN telecom_providers tp ON ((tp.id = pn.provider_id)))\n     JOIN packages pkg ON ((pkg.id = p.package_id)));"
            },
            {
                "name": "admin_payment_tasks",
                "schema": "public",
                "definition": " SELECT pt.id,\n    pt.protection_id,\n    p.customer_number_id,\n    COALESCE(pt.provider_id, pn.provider_id) AS provider_id,\n    u.full_name AS customer_name,\n    pn.number,\n    tp.name_ar AS provider_name,\n    pt.task_type,\n    pt.due_date AS due_at,\n    COALESCE(pt.telecom_due_at, pt.due_date) AS telecom_due_at,\n    COALESCE(pt.days_remaining, (ceil(EXTRACT(epoch FROM ((COALESCE(pt.telecom_due_at, pt.due_date) - now()) / (86400.0)::double precision))))::integer) AS days_remaining,\n    pt.status,\n    pt.completed_at,\n    pt.completed_by,\n    pt.telecom_reference,\n    pt.rescheduled_reason,\n    pt.scheduled_at,\n    pt.created_at,\n    pt.updated_at,\n    pt.classification_id,\n    pkg.price AS amount_snapshot,\n    pt.cycle_number,\n    pt.visible_from,\n    pt.planned_due_at\n   FROM ((((((payment_tasks pt\n     JOIN protections p ON ((p.id = pt.protection_id)))\n     JOIN customer_numbers cn ON ((cn.id = p.customer_number_id)))\n     JOIN users u ON ((u.id = cn.customer_id)))\n     JOIN phone_numbers pn ON ((pn.id = cn.phone_number_id)))\n     JOIN telecom_providers tp ON ((tp.id = COALESCE(pt.provider_id, pn.provider_id))))\n     JOIN packages pkg ON ((pkg.id = p.package_id)))\n  WHERE ((private.current_actor_type() = 'admin'::user_type) AND (pt.status <> 'completed'::task_status) AND (COALESCE(pt.visible_from, pt.due_date) <= now()));"
            },
            {
                "name": "customer_my_numbers",
                "schema": "public",
                "definition": " SELECT cn.id,\n    cn.customer_id,\n    cn.phone_number_id,\n    pn.number,\n    tp.id AS provider_id,\n    tp.name_ar AS provider_name_ar,\n    tp.name_en AS provider_name_en,\n    tp.code AS provider_code,\n    cn.custom_label,\n    cn.is_active,\n    cn.created_at,\n    p.id AS active_protection_id,\n    p.starts_at AS protection_starts_at,\n    p.expires_at AS protection_expires_at,\n    p.status AS protection_status\n   FROM (((customer_numbers cn\n     JOIN phone_numbers pn ON ((pn.id = cn.phone_number_id)))\n     JOIN telecom_providers tp ON ((tp.id = pn.provider_id)))\n     LEFT JOIN protections p ON (((p.customer_number_id = cn.id) AND (p.status = 'active'::protection_status))))\n  WHERE ((cn.customer_id = auth.uid()) OR (private.current_actor_type() = 'admin'::user_type));"
            },
            {
                "name": "customer_my_protections",
                "schema": "public",
                "definition": " SELECT p.id,\n    p.customer_number_id,\n    pn.number,\n    tp.name_ar AS provider_name,\n    pkg.name AS package_name,\n    p.starts_at,\n    p.expires_at,\n    p.status,\n    p.created_at\n   FROM ((((protections p\n     JOIN customer_numbers cn ON ((cn.id = p.customer_number_id)))\n     JOIN phone_numbers pn ON ((pn.id = cn.phone_number_id)))\n     JOIN telecom_providers tp ON ((tp.id = pn.provider_id)))\n     JOIN packages pkg ON ((pkg.id = p.package_id)))\n  WHERE (cn.customer_id = auth.uid());"
            },
            {
                "name": "my_profile",
                "schema": "public",
                "definition": " SELECT id,\n    user_type,\n    full_name,\n    email,\n    phone,\n    status,\n    role_id,\n    created_at,\n    updated_at\n   FROM users\n  WHERE (id = auth.uid());"
            },
            {
                "name": "decrypted_secrets",
                "schema": "vault",
                "definition": " SELECT id,\n    name,\n    description,\n    secret,\n    convert_from(vault._crypto_aead_det_decrypt(message => decode(secret, 'base64'::text), additional => convert_to((id)::text, 'utf8'::name), key_id => (0)::bigint, context => '\\x7067736f6469756d'::bytea, nonce => nonce), 'utf8'::name) AS decrypted_secret,\n    key_id,\n    nonce,\n    created_at,\n    updated_at\n   FROM vault.secrets s;"
            }
        ],
