                "definition": "CREATE OR REPLACE FUNCTION private.has_permission(p_permission text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n  select exists (\n    select 1\n    from public.users u\n    join public.role_permissions rp on rp.role_id = u.role_id\n    join public.permissions p on p.id = rp.permission_id\n    where u.id = auth.uid()\n      and u.user_type = 'admin'::public.user_type\n      and u.status = 'active'::public.user_status\n      and p.code = p_permission\n  );\n$function$\n",
