                "oid": "18820",
                "name": "add_customer_number",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_number text",
                "definition": "CREATE OR REPLACE FUNCTION public.add_customer_number(p_number text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_norm text;\n  v_provider_id uuid;\n  v_phone_id uuid;\n  v_cust_num_id uuid;\nbegin\n  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;\n  v_norm := public.normalize_phone(p_number);\n  if v_norm is null or length(v_norm) < 9 then\n    raise exception 'INVALID_PHONE_NUMBER';\n  end if;\n\n  v_provider_id := public.detect_provider_id(v_norm);\n  if v_provider_id is null then\n    raise exception 'PROVIDER_NOT_SUPPORTED';\n  end if;\n\n  -- Ensure exists in phone_numbers\n  insert into public.phone_numbers (provider_id, number)\n  values (v_provider_id, v_norm)\n  on conflict (number) do update set provider_id = excluded.provider_id\n  returning id into v_phone_id;\n\n  -- Link to customer_numbers\n  insert into public.customer_numbers (customer_id, phone_number_id, is_active)\n  values (auth.uid(), v_phone_id, true)\n  on conflict (customer_id, phone_number_id) do update set is_active = true\n  returning id into v_cust_num_id;\n\n  insert into public.audit_logs (actor_id, action, entity_type, entity_id, after_data)\n  values (auth.uid(), 'add_customer_number', 'customer_number', v_cust_num_id, jsonb_build_object('number', v_norm));\n\n  return v_cust_num_id;\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "uuid"
            },
            {
                "oid": "18830",
                "name": "admin_replace_provider_prefixes",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_provider_id uuid, p_prefixes text[]",
                "definition": "CREATE OR REPLACE FUNCTION public.admin_replace_provider_prefixes(p_provider_id uuid, p_prefixes text[])\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_count integer;\nbegin\n  if not private.has_permission('providers.manage') then raise exception 'PERMISSION_DENIED'; end if;\n  if not exists (select 1 from public.telecom_providers where id=p_provider_id) then raise exception 'PROVIDER_NOT_FOUND'; end if;\n  if exists (select 1 from unnest(coalesce(p_prefixes, '{}'::text[])) p where p !~ '^[0-9]+$' or length(p)=0) then raise exception 'PREFIX_INVALID'; end if;\n  if exists (\n    select 1 from unnest(coalesce(p_prefixes, '{}'::text[])) p group by p having count(*) > 1\n  ) then raise exception 'PREFIX_DUPLICATE'; end if;\n  if exists (\n    select 1 from unnest(coalesce(p_prefixes, '{}'::text[])) p\n    join public.provider_prefixes old on old.prefix=p and old.is_active and old.provider_id<>p_provider_id\n  ) then raise exception 'PREFIX_ALREADY_ASSIGNED'; end if;\n  update public.provider_prefixes\n    set is_active=false\n    where provider_id=p_provider_id and is_active\n      and prefix <> all(coalesce(p_prefixes, '{}'::text[]));\n  insert into public.provider_prefixes(provider_id,prefix,is_active)\n    select p_provider_id,p,true from unnest(coalesce(p_prefixes, '{}'::text[])) p\n    on conflict(provider_id,prefix) do update set is_active=true;\n  select count(*) into v_count from public.provider_prefixes where provider_id=p_provider_id and is_active;\n  insert into public.audit_logs(actor_id,action,entity_type,entity_id,after_data)\n    values(auth.uid(),'replace_provider_prefixes','telecom_provider',p_provider_id,jsonb_build_object('prefixes',coalesce(p_prefixes, '{}'::text[])));\n  return v_count;\nend; $function$\n",
                "volatility": "v",
                "return_type": "integer"
            },
            {
                "oid": "18831",
                "name": "admin_replace_role_permissions",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_role_id uuid, p_permission_codes text[]",
                "definition": "CREATE OR REPLACE FUNCTION public.admin_replace_role_permissions(p_role_id uuid, p_permission_codes text[])\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_count integer;\nbegin\n  if not private.has_permission('roles.manage') then raise exception 'PERMISSION_DENIED'; end if;\n  if not exists (select 1 from public.roles where id=p_role_id and is_active) then raise exception 'ROLE_NOT_FOUND'; end if;\n  if exists (\n    select 1 from unnest(coalesce(p_permission_codes, '{}'::text[])) code\n    where not exists(select 1 from public.permissions p where p.code=code)\n  ) then raise exception 'PERMISSION_NOT_FOUND'; end if;\n  delete from public.role_permissions where role_id=p_role_id;\n  insert into public.role_permissions(role_id,permission_id)\n    select p_role_id,p.id from public.permissions p\n    where p.code = any(coalesce(p_permission_codes, '{}'::text[]));\n  select count(*) into v_count from public.role_permissions where role_id=p_role_id;\n  insert into public.audit_logs(actor_id,action,entity_type,entity_id,after_data)\n    values(auth.uid(),'replace_role_permissions','role',p_role_id,jsonb_build_object('permission_codes',coalesce(p_permission_codes, '{}'::text[])));\n  return v_count;\nend; $function$\n",
