                "definition": "CREATE OR REPLACE FUNCTION public.admin_upsert_provider(p_id uuid, p_name text, p_code text, p_number_length integer, p_is_active boolean, p_sort_order integer)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_id uuid; v_code text;\nbegin\n  if not private.has_permission('providers.manage') then raise exception 'PERMISSION_DENIED'; end if;\n  if nullif(trim(p_name), '') is null then raise exception 'PROVIDER_NAME_REQUIRED'; end if;\n  if p_number_length not between 7 and 15 then raise exception 'NUMBER_LENGTH_INVALID'; end if;\n  v_code := lower(trim(p_code));\n  if v_code = '' then raise exception 'PROVIDER_CODE_REQUIRED'; end if;\n\n  if p_id is null then\n    insert into public.telecom_providers(name_ar, name_en, code, number_length, is_active, sort_order)\n    values(trim(p_name), trim(p_code), v_code, p_number_length, coalesce(p_is_active,true), coalesce(p_sort_order,0))\n    returning id into v_id;\n  else\n    update public.telecom_providers\n    set name_ar=trim(p_name), name_en=trim(p_code), code=v_code,\n        number_length=p_number_length, is_active=coalesce(p_is_active,true),\n        sort_order=coalesce(p_sort_order,0), updated_at=now()\n    where id=p_id returning id into v_id;\n    if v_id is null then raise exception 'PROVIDER_NOT_FOUND'; end if;\n  end if;\n  insert into public.audit_logs(actor_id, action, entity_type, entity_id, after_data)\n  values(auth.uid(), 'upsert_provider', 'telecom_provider', v_id,\n         jsonb_build_object('name',p_name,'code',v_code,'number_length',p_number_length));\n  return v_id;\nend; $function$\n",
