            {
                "oid": "18918",
                "name": "admin_upsert_task_classification",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_id uuid, p_task_settings_id uuid, p_name text, p_min_days integer, p_max_days integer, p_sort_order integer, p_is_active boolean",
                "definition": "CREATE OR REPLACE FUNCTION public.admin_upsert_task_classification(p_id uuid, p_task_settings_id uuid, p_name text, p_min_days integer, p_max_days integer, p_sort_order integer, p_is_active boolean)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n    v_id uuid;\n    v_provider uuid;\nbegin\n\n    if not private.has_permission('settings.manage') then\n        raise exception 'PERMISSION_DENIED';\n    end if;\n\n\n    if p_name is null\n       or trim(p_name) = '' then\n        raise exception 'INVALID_CLASSIFICATION';\n    end if;\n\n\n    if p_min_days is not null\n       and p_max_days is not null\n       and p_min_days > p_max_days then\n        raise exception 'INVALID_RANGE';\n    end if;\n\n\n    select provider_id\n    into v_provider\n    from public.task_settings\n    where id = p_task_settings_id\n      and is_active = true;\n\n\n    if v_provider is null then\n        raise exception 'TASK_SETTINGS_NOT_FOUND';\n    end if;\n\n\n    insert into public.task_time_classifications (\n        id,\n        task_settings_id,\n        provider_id,\n        classification,\n        name,\n        min_days_remaining,\n        max_days_remaining,\n        start_offset_hours,\n        end_offset_hours,\n        sort_order,\n        is_active\n    )\n    values (\n        coalesce(p_id, gen_random_uuid()),\n        p_task_settings_id,\n        v_provider,\n        trim(p_name),\n        trim(p_name),\n        p_min_days,\n        p_max_days,\n        coalesce(p_max_days, 0) * 24,\n        coalesce(p_min_days, 0) * 24,\n        p_sort_order,\n        p_is_active\n    )\n\n    on conflict (id)\n    do update set\n\n        task_settings_id =\n            excluded.task_settings_id,\n\n        provider_id =\n            excluded.provider_id,\n\n        classification =\n            excluded.classification,\n\n        name =\n            excluded.name,\n\n        min_days_remaining =\n            excluded.min_days_remaining,\n\n        max_days_remaining =\n            excluded.max_days_remaining,\n\n        start_offset_hours =\n            excluded.start_offset_hours,\n\n        end_offset_hours =\n            excluded.end_offset_hours,\n\n        sort_order =\n            excluded.sort_order,\n\n        is_active =\n            excluded.is_active\n\n    returning id into v_id;\n\n\n    return v_id;\n\nend;\n$function$\n",
