                "definition": "CREATE OR REPLACE FUNCTION public.admin_upsert_task_settings(p_provider_id uuid, p_first_task_enabled boolean, p_manual_reschedule_enabled boolean, p_interval_days integer, p_is_active boolean)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n    v_id uuid;\nbegin\n\n    if not private.has_permission('settings.manage') then\n        raise exception 'PERMISSION_DENIED';\n    end if;\n\n    if p_provider_id is null then\n        raise exception 'PROVIDER_REQUIRED';\n    end if;\n\n    if p_interval_days is null\n       or p_interval_days <= 0 then\n        raise exception 'INVALID_INTERVAL';\n    end if;\n\n    if not exists (\n        select 1\n        from public.telecom_providers\n        where id = p_provider_id\n    ) then\n        raise exception 'PROVIDER_NOT_FOUND';\n    end if;\n\n    insert into public.task_settings (\n        provider_id,\n        first_task_enabled,\n        manual_reschedule_enabled,\n        default_interval_days,\n        is_active\n    )\n    values (\n        p_provider_id,\n        p_first_task_enabled,\n        p_manual_reschedule_enabled,\n        p_interval_days,\n        p_is_active\n    )\n\n    on conflict (provider_id)\n    where provider_id is not null\n\n    do update set\n        first_task_enabled =\n            excluded.first_task_enabled,\n\n        manual_reschedule_enabled =\n            excluded.manual_reschedule_enabled,\n\n        default_interval_days =\n            excluded.default_interval_days,\n\n        is_active =\n            excluded.is_active,\n\n        updated_at = now()\n\n    returning id into v_id;\n\n\n    insert into public.audit_logs (\n        actor_id,\n        action,\n        entity_type,\n        entity_id,\n        after_data\n    )\n    values (\n        auth.uid(),\n        'upsert_task_settings',\n        'task_settings',\n        v_id,\n        jsonb_build_object(\n            'provider_id', p_provider_id,\n            'interval_days', p_interval_days,\n            'first_task_enabled', p_first_task_enabled,\n            'manual_reschedule_enabled',\n                p_manual_reschedule_enabled,\n            'is_active', p_is_active\n        )\n    );\n\n    return v_id;\n\nend;\n$function$\n",
