                "arguments": "p_provider_id uuid, p_first_task_enabled boolean, p_manual_reschedule_enabled boolean, p_interval_days integer, p_visibility_days_before integer DEFAULT 30, p_is_active boolean DEFAULT true",
                "definition": "CREATE OR REPLACE FUNCTION public.admin_upsert_task_settings(p_provider_id uuid, p_first_task_enabled boolean, p_manual_reschedule_enabled boolean, p_interval_days integer, p_visibility_days_before integer DEFAULT 30, p_is_active boolean DEFAULT true)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_id uuid;\nbegin\n  if not private.has_permission('settings.manage') then raise exception 'PERMISSION_DENIED'; end if;\n  if p_interval_days is null or p_interval_days <= 0 then raise exception 'INVALID_INTERVAL'; end if;\n  if p_visibility_days_before is null or p_visibility_days_before < 0 then raise exception 'INVALID_VISIBILITY_WINDOW'; end if;\n  insert into public.task_settings(provider_id, first_task_enabled, manual_reschedule_enabled, default_interval_days, visibility_days_before, is_active)\n  values (p_provider_id, p_first_task_enabled, p_manual_reschedule_enabled, p_interval_days, p_visibility_days_before, p_is_active)\n  on conflict (provider_id) where provider_id is not null do update set\n    first_task_enabled = excluded.first_task_enabled,\n    manual_reschedule_enabled = excluded.manual_reschedule_enabled,\n    default_interval_days = excluded.default_interval_days,\n    visibility_days_before = excluded.visibility_days_before,\n    is_active = excluded.is_active,\n    updated_at = now()\n  returning id into v_id;\n  return v_id;\nend; $function$\n",
