            {
                "oid": "18825",
                "name": "approve_protection_request",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_request_id uuid",
                "definition": "CREATE OR REPLACE FUNCTION public.approve_protection_request(p_request_id uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n    v_req record;\n    v_pkg record;\n    v_prot uuid;\n    v_provider uuid;\n    v_first_task_enabled boolean;\nbegin\n\n    if not private.has_permission('requests.approve') then\n        raise exception 'PERMISSION_DENIED';\n    end if;\n\n\n    -- Lock request\n    select *\n    into v_req\n    from public.protection_requests\n    where id = p_request_id\n    for update;\n\n\n    if not found then\n        raise exception 'REQUEST_NOT_FOUND';\n    end if;\n\n\n    if v_req.status not in (\n        'under_review',\n        'pending_payment_verification'\n    )\n    then\n        raise exception 'INVALID_REQUEST_STATUS';\n    end if;\n\n\n    -- Package\n    select *\n    into v_pkg\n    from public.packages\n    where id = v_req.package_id\n      and is_active = true;\n\n\n    if not found then\n        raise exception 'PACKAGE_NOT_FOUND';\n    end if;\n\n\n    -- Provider\n    select pn.provider_id\n    into v_provider\n\n    from public.customer_numbers cn\n\n    join public.phone_numbers pn\n        on pn.id = cn.phone_number_id\n\n    where cn.id = v_req.customer_number_id;\n\n\n    if v_provider is null then\n        raise exception 'PROVIDER_NOT_FOUND';\n    end if;\n\n\n    -- Provider settings\n    select coalesce(first_task_enabled, true)\n    into v_first_task_enabled\n\n    from public.task_settings\n\n    where provider_id = v_provider\n      and is_active = true\n\n    limit 1;\n\n\n    v_first_task_enabled :=\n        coalesce(v_first_task_enabled, true);\n\n\n    -- Create protection\n    insert into public.protections (\n        customer_number_id,\n        package_id,\n        request_id,\n        starts_at,\n        expires_at,\n        status\n    )\n\n    values (\n        v_req.customer_number_id,\n        v_req.package_id,\n        v_req.id,\n        now(),\n        now() +\n            (v_pkg.duration_days || ' days')::interval,\n        'active'\n    )\n\n    returning id into v_prot;\n\n\n    -- Approve request\n    update public.protection_requests\n\n    set\n        status = 'approved',\n        reviewed_at = now(),\n        reviewed_by = auth.uid(),\n        updated_at = now()\n\n    where id = p_request_id;\n\n\n    -- Initial activation task\n    if v_first_task_enabled then\n\n        insert into public.payment_tasks (\n            protection_id,\n            provider_id,\n            task_type,\n            due_date,\n            telecom_due_at,\n            visible_from,\n            planned_due_at,\n            status\n        )\n\n        values (\n            v_prot,\n            v_provider,\n            'initial_activation',\n            now(),\n            now(),\n            now(),\n            now(),\n            'due'\n        );\n\n    end if;\n\n\n    -- Financial transaction\n    insert into public.financial_transactions (\n        type,\n        amount,\n        currency,\n        reference_id,\n        notes,\n        created_by\n    )\n\n    values (\n        'customer_payment',\n        v_pkg.price,\n        'YER',\n        v_prot,\n        'رسوم حماية معتمدة',\n        auth.uid()\n    );\n\n\n    -- Customer notification\n    insert into public.client_notifications (\n        customer_id,\n        title,\n        message,\n        type,\n        related_entity_type,\n        related_entity_id\n    )\n\n    values (\n        v_req.customer_id,\n        'تم تفعيل الحماية',\n        'تمت الموافقة على طلب الحماية وبدأت فترة الحماية بنجاح',\n        'protection_started',\n        'protection',\n        v_prot\n    );\n\n\n    -- Audit\n    insert into public.audit_logs (\n        actor_id,\n        action,\n        entity_type,\n        entity_id\n    )\n\n    values (\n        auth.uid(),\n        'approve_protection_request',\n        'protection',\n        v_prot\n    );\n\n\n    return v_prot;\n\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "uuid"
            },
