            {
                "oid": "18828",
                "name": "complete_payment_task",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_task_id uuid, p_telecom_ref text",
                "definition": "CREATE OR REPLACE FUNCTION public.complete_payment_task(p_task_id uuid, p_telecom_ref text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n    v_task record;\n    v_interval integer;\n    v_visibility integer;\n    v_next timestamptz;\n    v_provider uuid;\nbegin\n\n    if not private.has_permission('tasks.complete') then\n        raise exception 'PERMISSION_DENIED';\n    end if;\n\n\n    select *\n    into v_task\n    from public.payment_tasks\n    where id = p_task_id\n    for update;\n\n\n    if not found then\n        raise exception 'TASK_NOT_FOUND';\n    end if;\n\n\n    if v_task.status = 'completed' then\n        return true;\n    end if;\n\n\n    -- Complete current task\n    update public.payment_tasks\n\n    set\n        status = 'completed',\n        completed_at = now(),\n        completed_by = auth.uid(),\n        telecom_reference = trim(p_telecom_ref),\n        updated_at = now()\n\n    where id = p_task_id;\n\n\n    -- Resolve provider\n    select\n        coalesce(\n            v_task.provider_id,\n            pn.provider_id\n        )\n    into v_provider\n\n    from public.protections p\n\n    join public.customer_numbers cn\n        on cn.id = p.customer_number_id\n\n    join public.phone_numbers pn\n        on pn.id = cn.phone_number_id\n\n    where p.id = v_task.protection_id;\n\n\n    if v_provider is null then\n        raise exception 'PROVIDER_NOT_FOUND';\n    end if;\n\n\n    -- Provider task settings\n    select\n        coalesce(default_interval_days, 90),\n        coalesce(visibility_days_before, 30)\n\n    into\n        v_interval,\n        v_visibility\n\n    from public.task_settings\n\n    where provider_id = v_provider\n      and is_active = true\n\n    limit 1;\n\n\n    v_interval := coalesce(v_interval, 90);\n    v_visibility := coalesce(v_visibility, 30);\n\n\n    -- Calculate next recurring task\n    v_next :=\n        now() + (v_interval || ' days')::interval;\n\n\n    -- Only create next task if protection is still active\n    -- and next task is before protection expiration.\n    if exists (\n        select 1\n        from public.protections\n        where id = v_task.protection_id\n          and status = 'active'\n          and expires_at > v_next\n    )\n    then\n\n        insert into public.payment_tasks (\n            protection_id,\n            provider_id,\n            task_type,\n            due_date,\n            telecom_due_at,\n            planned_due_at,\n            visible_from,\n            status\n        )\n\n        values (\n            v_task.protection_id,\n            v_provider,\n            'recurring',\n            v_next,\n            v_next,\n            v_next,\n            v_next -\n                (v_visibility || ' days')::interval,\n            'due'\n        );\n\n    end if;\n\n\n    -- Audit\n    insert into public.audit_logs (\n        actor_id,\n        action,\n        entity_type,\n        entity_id,\n        after_data\n    )\n\n    values (\n        auth.uid(),\n        'complete_payment_task',\n        'payment_task',\n        p_task_id,\n        jsonb_build_object(\n            'telecom_reference', p_telecom_ref,\n            'provider_id', v_provider,\n            'next_due_at', v_next\n        )\n    );\n\n\n    return true;\n\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "boolean"
            },
