            {
                "oid": "18816",
                "name": "detect_provider_id",
                "schema": "public",
                "language": "plpgsql",
                "security": "INVOKER",
                "arguments": "p_phone text",
                "definition": "CREATE OR REPLACE FUNCTION public.detect_provider_id(p_phone text)\n RETURNS uuid\n LANGUAGE plpgsql\n STABLE\nAS $function$\ndeclare\n  v_norm text;\n  v_provider_id uuid;\nbegin\n  v_norm := public.normalize_phone(p_phone);\n  if v_norm is null or length(v_norm) < 2 then return null; end if;\n\n  select pp.provider_id into v_provider_id\n  from public.provider_prefixes pp\n  where pp.is_active\n    and v_norm like (pp.prefix || '%')\n  order by length(pp.prefix) desc\n  limit 1;\n\n  return v_provider_id;\nend;\n$function$\n",
                "volatility": "s",
                "return_type": "uuid"
            },
