            {
                "oid": "18832",
                "name": "get_admin_dashboard_summary",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "",
                "definition": "CREATE OR REPLACE FUNCTION public.get_admin_dashboard_summary()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_total_customers integer;\n  v_total_numbers integer;\n  v_active_protections integer;\n  v_pending_requests integer;\n  v_due_tasks integer;\n  v_total_revenue numeric;\nbegin\n  if not (private.has_permission('overview.read') or private.current_actor_type() = 'admin') then\n    raise exception 'PERMISSION_DENIED';\n  end if;\n\n  select count(*) into v_total_customers from public.users where user_type = 'customer';\n  select count(*) into v_total_numbers from public.customer_numbers where is_active;\n  select count(*) into v_active_protections from public.protections where status = 'active';\n  select count(*) into v_pending_requests from public.protection_requests where status in ('pending_payment_verification', 'under_review');\n  select count(*) into v_due_tasks from public.payment_tasks where status = 'due';\n  select coalesce(sum(amount), 0) into v_total_revenue from public.financial_transactions where type = 'customer_payment';\n\n  return jsonb_build_object(\n    'total_customers', v_total_customers,\n    'total_numbers', v_total_numbers,\n    'active_protections', v_active_protections,\n    'pending_requests', v_pending_requests,\n    'due_tasks', v_due_tasks,\n    'total_revenue', v_total_revenue\n  );\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "jsonb"
            },
            {
                "oid": "18819",
                "name": "get_current_actor",
                "schema": "public",
                "language": "sql",
                "security": "DEFINER",
                "arguments": "",
                "definition": "CREATE OR REPLACE FUNCTION public.get_current_actor()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n  select coalesce((\n    select jsonb_build_object(\n      'id', u.id,\n      'user_type', u.user_type,\n      'full_name', u.full_name,\n      'email', coalesce(u.email, ''),\n      'phone', coalesce(u.phone, ''),\n      'status', u.status,\n      'role_id', u.role_id,\n      'role_name', coalesce(r.name, ''),\n      'role_code', lower(replace(coalesce(r.name, ''), ' ', '_'))\n    )\n    from public.users u\n    left join public.roles r on r.id = u.role_id\n    where u.id = auth.uid() and u.status = 'active'\n  ), '{}'::jsonb);\n$function$\n",
                "volatility": "s",
                "return_type": "jsonb"
            },
            {
                "oid": "18817",
                "name": "handle_auth_user_created",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "",
                "definition": "CREATE OR REPLACE FUNCTION public.handle_auth_user_created()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_phone text;\n  v_email text;\n  v_name text;\n  v_type text;\nbegin\n  -- Extract phone\n  v_phone := coalesce(\n    new.raw_user_meta_data->>'phone',\n    new.phone\n  );\n  v_phone := public.normalize_phone(v_phone);\n\n  -- Extract email\n  v_email := nullif(lower(trim(coalesce(new.email, ''))), '');\n\n  -- Extract full name\n  v_name := coalesce(\n    nullif(trim(new.raw_user_meta_data->>'full_name'), ''),\n    'مستخدم أمان'\n  );\n\n  -- User type defaults to customer\n  v_type := coalesce(nullif(trim(new.raw_user_meta_data->>'user_type'), ''), 'customer');\n\n  insert into public.users (id, user_type, full_name, email, phone, status)\n  values (\n    new.id,\n    case when v_type = 'admin' then 'admin'::public.user_type else 'customer'::public.user_type end,\n    v_name,\n    v_email,\n    v_phone,\n    'active'::public.user_status\n  )\n  on conflict (id) do update\n  set\n    full_name = excluded.full_name,\n    phone = coalesce(excluded.phone, public.users.phone),\n    email = coalesce(excluded.email, public.users.email),\n    updated_at = now();\n\n  return new;\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "trigger"
            },
