            {
                "oid": "18815",
                "name": "normalize_phone",
                "schema": "public",
                "language": "plpgsql",
                "security": "INVOKER",
                "arguments": "p_raw text",
                "definition": "CREATE OR REPLACE FUNCTION public.normalize_phone(p_raw text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\ndeclare\n  v_digits text;\nbegin\n  if p_raw is null then return null; end if;\n  v_digits := regexp_replace(p_raw, '[^0-9]', '', 'g');\n  if length(v_digits) = 9 then\n    return v_digits;\n  elsif length(v_digits) = 10 and v_digits like '0%' then\n    return substr(v_digits, 2);\n  elsif length(v_digits) = 12 and v_digits like '967%' then\n    return substr(v_digits, 4);\n  elsif length(v_digits) > 9 then\n    return right(v_digits, 9);\n  else\n    return v_digits;\n  end if;\nend;\n$function$\n",
                "volatility": "i",
                "return_type": "text"
            },
