            {
                "oid": "18827",
                "name": "reject_protection_request",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_request_id uuid, p_rejection_reason text",
                "definition": "CREATE OR REPLACE FUNCTION public.reject_protection_request(p_request_id uuid, p_rejection_reason text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_req record;\nbegin\n  if not private.has_permission('requests.reject') then raise exception 'PERMISSION_DENIED'; end if;\n\n  select * into v_req from public.protection_requests where id = p_request_id for update;\n  if not found then raise exception 'REQUEST_NOT_FOUND'; end if;\n\n  update public.protection_requests\n  set\n    status = 'rejected',\n    rejection_reason = trim(p_rejection_reason),\n    reviewed_at = now(),\n    reviewed_by = auth.uid(),\n    updated_at = now()\n  where id = p_request_id;\n\n  insert into public.client_notifications (customer_id, title, message, type, related_entity_type, related_entity_id)\n  values (v_req.customer_id, 'تم رفض طلب الحماية', coalesce(trim(p_rejection_reason), 'تعذر قبول الطلب، يرجى مراجعة سبب الرفض وتعديل البيانات'), 'request_rejected', 'protection_request', p_request_id);\n\n  insert into public.audit_logs (actor_id, action, entity_type, entity_id, after_data)\n  values (auth.uid(), 'reject_protection_request', 'protection_request', p_request_id, jsonb_build_object('reason', p_rejection_reason));\n\n  return true;\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "boolean"
            },
            {
                "oid": "18829",
                "name": "reschedule_payment_task",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_task_id uuid, p_new_due_date timestamp with time zone, p_reason text DEFAULT NULL::text",
                "definition": "CREATE OR REPLACE FUNCTION public.reschedule_payment_task(p_task_id uuid, p_new_due_date timestamp with time zone, p_reason text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  if not private.has_permission('tasks.reschedule') then raise exception 'PERMISSION_DENIED'; end if;\n  if p_new_due_date <= now() then raise exception 'INVALID_DUE_DATE'; end if;\n\n  update public.payment_tasks\n  set\n    due_date = p_new_due_date,\n    rescheduled_reason = p_reason,\n    updated_at = now()\n  where id = p_task_id and status = 'due';\n\n  if not found then raise exception 'TASK_NOT_FOUND'; end if;\n\n  insert into public.audit_logs (actor_id, action, entity_type, entity_id, after_data)\n  values (auth.uid(), 'reschedule_payment_task', 'payment_task', p_task_id, jsonb_build_object('new_due_date', p_new_due_date, 'reason', p_reason));\n\n  return true;\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "boolean"
            },
            {
                "oid": "18823",
                "name": "resubmit_rejected_request",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_request_id uuid, p_package_id uuid, p_wallet_id uuid, p_transfer_ref text",
                "definition": "CREATE OR REPLACE FUNCTION public.resubmit_rejected_request(p_request_id uuid, p_package_id uuid, p_wallet_id uuid, p_transfer_ref text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;\n\n  update public.protection_requests\n  set\n    package_id = p_package_id,\n    payment_method_id = p_wallet_id,\n    transfer_reference = trim(p_transfer_ref),\n    status = 'pending_payment_verification',\n    rejection_reason = null,\n    updated_at = now()\n  where id = p_request_id and customer_id = auth.uid() and status = 'rejected';\n\n  if not found then raise exception 'REQUEST_NOT_RESUBMITTABLE'; end if;\n\n  insert into public.admin_notifications (title, message, type, related_entity_type, related_entity_id)\n  values ('إعادة تقديم طلب حماية', 'تم تعديل وإعادة تقديم طلب حماية مرفوض للمراجعة', 'request_submitted', 'protection_request', p_request_id);\n\n  insert into public.audit_logs (actor_id, action, entity_type, entity_id)\n  values (auth.uid(), 'resubmit_rejected_request', 'protection_request', p_request_id);\n\n  return true;\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "boolean"
            },
            {
                "oid": "18821",
                "name": "submit_protection_request",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_number_id uuid, p_package_id uuid, p_wallet_id uuid, p_transfer_ref text, p_idempotency_key text DEFAULT NULL::text",
                "definition": "CREATE OR REPLACE FUNCTION public.submit_protection_request(p_number_id uuid, p_package_id uuid, p_wallet_id uuid, p_transfer_ref text, p_idempotency_key text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_request_id uuid;\n  v_existing uuid;\nbegin\n  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;\n  if not exists (select 1 from public.customer_numbers where id = p_number_id and customer_id = auth.uid()) then\n    raise exception 'NUMBER_NOT_FOUND';\n  end if;\n  if not exists (select 1 from public.packages where id = p_package_id and is_active) then\n    raise exception 'PACKAGE_NOT_FOUND';\n  end if;\n  if not exists (select 1 from public.payment_methods where id = p_wallet_id and is_active) then\n    raise exception 'PAYMENT_METHOD_NOT_FOUND';\n  end if;\n\n  if p_idempotency_key is not null then\n    select id into v_existing from public.protection_requests where idempotency_key = p_idempotency_key;\n    if v_existing is not null then return v_existing; end if;\n  end if;\n\n  insert into public.protection_requests (\n    customer_id,\n    customer_number_id,\n    package_id,\n    payment_method_id,\n    transfer_reference,\n    idempotency_key,\n    status\n  ) values (\n    auth.uid(),\n    p_number_id,\n    p_package_id,\n    p_wallet_id,\n    trim(p_transfer_ref),\n    p_idempotency_key,\n    'pending_payment_verification'\n  ) returning id into v_request_id;\n\n  insert into public.admin_notifications (title, message, type, related_entity_type, related_entity_id)\n  values ('طلب حماية جديد', 'تم تقديم طلب حماية جديد يتطلب مراجعة الدفع', 'request_submitted', 'protection_request', v_request_id);\n\n  insert into public.audit_logs (actor_id, action, entity_type, entity_id)\n  values (auth.uid(), 'submit_protection_request', 'protection_request', v_request_id);\n\n  return v_request_id;\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "uuid"
            },
            {
                "oid": "18822",
                "name": "submit_renewal_request",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_protection_id uuid, p_package_id uuid, p_wallet_id uuid, p_transfer_ref text",
                "definition": "CREATE OR REPLACE FUNCTION public.submit_renewal_request(p_protection_id uuid, p_package_id uuid, p_wallet_id uuid, p_transfer_ref text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_number_id uuid;\n  v_req_id uuid;\nbegin\n  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;\n\n  select p.customer_number_id into v_number_id\n  from public.protections p\n  join public.customer_numbers cn on cn.id = p.customer_number_id\n  where p.id = p_protection_id and cn.customer_id = auth.uid();\n\n  if v_number_id is null then raise exception 'PROTECTION_NOT_FOUND'; end if;\n\n  v_req_id := public.submit_protection_request(v_number_id, p_package_id, p_wallet_id, p_transfer_ref);\n\n  insert into public.audit_logs (actor_id, action, entity_type, entity_id)\n  values (auth.uid(), 'submit_renewal_request', 'protection_request', v_req_id);\n\n  return v_req_id;\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "uuid"
            },
            {
                "oid": "18833",
                "name": "update_my_profile",
                "schema": "public",
                "language": "plpgsql",
                "security": "DEFINER",
                "arguments": "p_full_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text",
                "definition": "CREATE OR REPLACE FUNCTION public.update_my_profile(p_full_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;\n\n  update public.users\n  set\n    full_name = coalesce(nullif(trim(p_full_name), ''), full_name),\n    email = coalesce(nullif(lower(trim(p_email)), ''), email),\n    updated_at = now()\n  where id = auth.uid();\n\n  return true;\nend;\n$function$\n",
                "volatility": "v",
                "return_type": "boolean"
            },
