                "definition": "CREATE OR REPLACE FUNCTION public.verify_request_payment(p_request_id uuid, p_verified boolean, p_note text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  if not private.has_permission('finance.verify') then raise exception 'PERMISSION_DENIED'; end if;\n\n  update public.protection_requests\n  set\n    status = case when p_verified then 'under_review'::public.request_status else 'rejected'::public.request_status end,\n    payment_verified_at = case when p_verified then now() else null end,\n    payment_verified_by = auth.uid(),\n    verified_note = p_note,\n    updated_at = now()\n  where id = p_request_id;\n\n  if not found then raise exception 'REQUEST_NOT_FOUND'; end if;\n\n  insert into public.audit_logs (actor_id, action, entity_type, entity_id, after_data)\n  values (auth.uid(), 'verify_payment', 'protection_request', p_request_id, jsonb_build_object('verified', p_verified, 'note', p_note));\n\n  return true;\nend;\n$function$\n",
